const dayKey = (d = new Date()) => d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
function parseCsv(text:string):string[][] {
 const rows:string[][]=[];let row:string[]=[];let field='';let quoted=false;
 for(let i=0;i<text.length;i++){
  const ch=text[i];
  if(ch==='"'){
   if(quoted&&text[i+1]==='"'){field+='"';i++;}
   else quoted=!quoted;
  }else if(ch===','&&!quoted){row.push(field);field='';}
  else if((ch==='\n'||ch==='\r')&&!quoted){
   if(ch==='\r'&&text[i+1]==='\n')i++;
   row.push(field);
   if(row.some(value=>value.length>0))rows.push(row);
   row=[];field='';
   if(rows.length>=60)return rows;
  }else field+=ch;
 }
 row.push(field);
 if(row.some(value=>value.length>0)&&rows.length<60)rows.push(row);
 if(rows.length>0&&rows[0][0]?.startsWith('\uFEFF'))rows[0][0]=rows[0][0].slice(1);
 return rows;
}
const readSaved = <T,>(key:string, fallback:T):T => { try { const v = localStorage.getItem(key); return v === null ? fallback : JSON.parse(v) as T; } catch { return fallback; } };
function useSaved<T>(key:string, initial:T) {
 const [value,setValue] = useState<T>(()=>readSaved(key,initial));
 useEffect(()=>{ try { localStorage.setItem(key,JSON.stringify(value)); } catch { /* storage can be disabled */ } },[key,value]);
 return [value,setValue] as const;
}
