 const [running,setRunning]=useState(false);
 const [timer,setTimer]=useState(300);
 const [left,setLeft]=useState(300);
 const [timerRunning,setTimerRunning]=useState(false);
 const [timerDeadline,setTimerDeadline]=useState<number|null>(null);
 const [timerMinutesInput,setTimerMinutesInput]=useState('5');
 const [timerSecondsInput,setTimerSecondsInput]=useState('0');
 const [durationError,setDurationError]=useState('');
 const [alarmSoundEnabled,setAlarmSoundEnabled]=useSaved<boolean>('aeroshell.clock.timer.sound.v1',true);
 const timerAudioRef=useRef<AudioContext|null>(null);
 const timerAlarmPlayed=useRef(false);
 const ensureTimerAudio=()=>{try{if(!timerAudioRef.current||timerAudioRef.current.state==='closed')timerAudioRef.current=new AudioContext();void timerAudioRef.current.resume().catch(()=>{});}catch{/* visual countdown remains available without Web Audio */}};
 const playTimerAlarm=useCallback(()=>{if(!alarmSoundEnabled||volume<=0)return;const context=timerAudioRef.current;if(!context||context.state==='closed')return;void context.resume().then(()=>{const nowAt=context.currentTime+0.025;[784,988,784,1174].forEach((frequency,index)=>{const start=nowAt+index*0.25;const oscillator=context.createOscillator();const gain=context.createGain();oscillator.type='triangle';oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(0.0001,start);gain.gain.exponentialRampToValueAtTime(0.58*(volume/100),start+0.02);gain.gain.exponentialRampToValueAtTime(0.0001,start+0.18);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(start);oscillator.stop(start+0.2);});}).catch(()=>{});},[alarmSoundEnabled,volume]);
 useEffect(()=>{const id=setInterval(()=>{setNow(new Date());if(running)setElapsed(value=>value+1);},1000);return()=>clearInterval(id);},[running]);
 useEffect(()=>{if(!timerRunning||timerDeadline===null)return;const tick=()=>{const remaining=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));setLeft(remaining);if(remaining===0){setTimerRunning(false);setTimerDeadline(null);if(!timerAlarmPlayed.current){timerAlarmPlayed.current=true;playTimerAlarm();}}};const id=window.setInterval(tick,200);tick();return()=>window.clearInterval(id);},[timerRunning,timerDeadline,playTimerAlarm]);
 useEffect(()=>()=>{const context=timerAudioRef.current;if(context&&context.state!=='closed')void context.close().catch(()=>{});},[]);
