 const applyTimer=()=>{const mins=Number(timerMinutesInput),secs=Number(timerSecondsInput);if(!Number.isInteger(mins)||!Number.isInteger(secs)||mins<0||mins>999||secs<0||secs>59){setDurationError('Use whole minutes from 0–999 and seconds from 0–59.');return;}const total=mins*60+secs;if(total<1){setDurationError('Set a countdown of at least one second.');return;}setTimer(total);setLeft(total);setTimerRunning(false);setTimerDeadline(null);timerAlarmPlayed.current=false;setDurationError('');};
 const startTimer=()=>{if(timerRunning){const remaining=timerDeadline===null?left:Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));setLeft(remaining);setTimerRunning(false);setTimerDeadline(null);return;}const base=left>0?left:timer;if(left===0){timerAlarmPlayed.current=false;setLeft(base);}ensureTimerAudio();setTimerDeadline(Date.now()+base*1000);setTimerRunning(true);};
