 const startReaction=()=>{if(reactionPhase==='waiting'){if(reactionTimer.current!==null)window.clearTimeout(reactionTimer.current);reactionTimer.current=null;setReactionPhase('early');return;}if(reactionPhase==='go'){const ms=Math.round(performance.now()-reactionStarted.current);setReactionLast(ms);setReactionPhase('idle');setScores(old=>({...old,reaction:old.reaction?Math.min(old.reaction,ms):ms}));return;}setReactionPhase('waiting');setReactionLast(null);reactionTimer.current=window.setTimeout(()=>{reactionStarted.current=performance.now();setReactionPhase('go');reactionTimer.current=null;},900+Math.random()*2200);};
 const answerMath=(value:number)=>{setMathAnswered(count=>count+1);if(value===mathQuestion.answer){setMathScore(score=>score+1);setMathFeedback('Correct! +1 point. Next question…');}else setMathFeedback('Not quite — the correct answer was '+mathQuestion.answer+'. Try the next one.');setMathQuestion(createMathQuestion());};
