 useEffect(()=>{if(game!=='snake'||!snakeOn||!active)return;const id=setInterval(()=>{setSnake(current=>{const head=current[0]+dir;if(head<0||head>=100||(dir===1&&head%10===0)||(dir===-1&&head%10===9)||current.includes(head)){setSnakeOn(false);setSnakeEnded(true);setScores(sc=>({...sc,snake:Math.max(sc.snake??0,current.length-3)}));return current;}if(head===food){const grown=[head,...current];const nextFood=createSnakeFood(grown);if(nextFood===null){setSnakeOn(false);setSnakeEnded(true);setScores(sc=>({...sc,snake:Math.max(sc.snake??0,grown.length-3)}));return grown;}setFood(nextFood);return grown;}return [head,...current.slice(0,-1)];});},Math.max(55,Math.min(400,snakeSpeed)));return()=>clearInterval(id);},[game,snakeOn,active,dir,food,snakeSpeed,setScores]);
